import js from '@eslint/js'
import stylistic from '@stylistic/eslint-plugin'
import betterTailwindcss from 'eslint-plugin-better-tailwindcss'
import perfectionist from 'eslint-plugin-perfectionist'
import pluginVue from 'eslint-plugin-vue'
import { defineConfig, globalIgnores } from 'eslint/config'
import globals from 'globals'
import tseslint from 'typescript-eslint'

/** The apps using Tailwind; class rules read each one's `src/main.css`, so they know its theme. */
const TAILWIND_APPS = ['apps/studio', 'apps/site', 'apps/sample']

export default defineConfig(
  // Generated by the apps' unplugins (routes, auto-imports, components); committed so typecheck needs no build.
  globalIgnores(['**/dist/', '**/dist-server/', '**/coverage/', '**/node_modules/', 'apps/*/src/*.d.ts', '!apps/*/src/env.d.ts']),
  js.configs.recommended,
  tseslint.configs.strictTypeChecked,
  tseslint.configs.stylisticTypeChecked,
  pluginVue.configs['flat/recommended'],
  // Formatting is enforced by ESLint Stylistic (`pnpm lint:fix` formats); there is no Prettier.
  stylistic.configs.customize({ indent: 2, quotes: 'single', semi: false, braceStyle: '1tbs', arrowParens: true }),
  {
    languageOptions: {
      globals: { ...globals.browser, ...globals.node },
      parserOptions: {
        projectService: true,
        tsconfigRootDir: import.meta.dirname,
        extraFileExtensions: ['.vue'],
      },
    },
    plugins: { perfectionist },
    rules: {
      '@typescript-eslint/consistent-type-imports': 'error',
      '@typescript-eslint/no-import-type-side-effects': 'error',
      '@typescript-eslint/restrict-template-expressions': ['error', { allowNumber: true }],
      '@typescript-eslint/no-unused-vars': ['error', { ignoreRestSiblings: true }],
      // `() => update()` reads better than `() => { update() }` for callbacks.
      '@typescript-eslint/no-confusing-void-expression': ['error', { ignoreArrowShorthand: true }],
      // Say where code comes from: `@/x` is this package's src/x, `~/x` is the repo root.
      'no-restricted-imports': ['error', {
        patterns: [{ regex: '^\\.\\./', message: 'Use @/ (this package\'s src) or ~/ (the repo root) instead of a parent-relative path.' }],
      }],
      // noUncheckedIndexedAccess makes `!` the honest way to say "this index exists".
      '@typescript-eslint/no-non-null-assertion': 'off',
      // Imports: every type import first, then node:, then packages, then this repo (`~/`, `@/`), then relative.
      'perfectionist/sort-imports': ['error', {
        groups: ['type-import', 'value-builtin', 'value-external', 'value-internal', ['value-parent', 'value-sibling', 'value-index'], 'side-effect', 'side-effect-style', 'unknown'],
        internalPattern: ['^~/.+', '^@/.+', '^virtual:.+'],
        newlinesBetween: 0,
      }],
      'perfectionist/sort-named-imports': 'error',
      'perfectionist/sort-named-exports': 'error',
    },
  },
  {
    files: ['**/*.vue'],
    languageOptions: { parserOptions: { parser: tseslint.parser } },
    rules: {
      // TypeScript owns undefined names (vue-tsc runs in CI); ESLint can't see the auto-imports.
      'no-undef': 'off',
      // ESLint's TypeScript can't read types from other .vue files (vue-tsc can, and checks them),
      // so a component's exposed API looks like an error type here.
      '@typescript-eslint/no-unsafe-argument': 'off',
      '@typescript-eslint/no-unsafe-assignment': 'off',
      '@typescript-eslint/no-unsafe-call': 'off',
      '@typescript-eslint/no-unsafe-member-access': 'off',
      '@typescript-eslint/no-unsafe-return': 'off',
    },
  },
  {
    // Deliberately single-word components: the site's mark and glossary term, Studio's panels.
    files: ['**/*.vue'],
    rules: {
      'vue/multi-word-component-names': ['error', { ignores: ['Mark', 'Term', 'Gallery', 'Inspector', 'Notices', 'Stage'] }],
    },
  },
  {
    // File-based routes and ui primitives: filenames are URL segments or deliberate single words,
    // and optional props are typed as optional rather than given defaults.
    files: ['apps/*/src/pages/**/*.vue', 'apps/*/src/components/ui/**/*.vue', 'packages/vue/src/**/*.vue'],
    rules: { 'vue/multi-word-component-names': 'off', 'vue/require-default-prop': 'off' },
  },
  // Tailwind: canonical classes (`w-254`, not `w-[1016px]`), a consistent order, and no unknown,
  // duplicate or conflicting classes, checked against each app's own theme. `lint:fix` rewrites them.
  ...TAILWIND_APPS.map((app) => ({
    files: [`${app}/src/**/*.{ts,vue}`],
    plugins: { 'better-tailwindcss': betterTailwindcss },
    // Resolved from the app, where tailwindcss is installed.
    settings: { 'better-tailwindcss': { cwd: app, entryPoint: 'src/main.css' } },
    rules: {
      ...betterTailwindcss.configs['recommended-error'].rules,
      // Long class lists stay on one line, like the rest of the template.
      'better-tailwindcss/enforce-consistent-line-wrapping': 'off' as const,
    },
  })),
  {
    // Test fakes are full of no-op methods and one-line stubs.
    files: ['**/test/**'],
    rules: {
      '@typescript-eslint/no-empty-function': 'off',
      '@typescript-eslint/require-await': 'off',
      '@stylistic/max-statements-per-line': 'off',
      // Tests mount small inline components next to each other.
      'vue/one-component-per-file': 'off',
    },
  },
)
